// VT-4 (voice-SPEC V-11.1): writes src/Marrow.Core/Port/Voice/Orb/OrbSeedData.cs from seeds.json (the owner's pasted exports, copied byte for
// byte beside this script by make-vt4-fixtures.js). The two presets' stateSeeds travel into the port as float literals: each number is the JSON
// text of the double, with an `f` suffix, so the C# compiler rounds it to the same float32 that `new Float32Array(...)` makes in the design.
// The file carries the SHA-256 of seeds.json; OrbSeedsTests fails when the two differ, so a changed seeds.json cannot be missed.
//
//   node make-orb-seed-source.js [--out <OrbSeedData.cs>]
'use strict';
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const bytes = fs.readFileSync(path.join(__dirname, 'seeds.json'));
const seeds = JSON.parse(bytes.toString('utf8'));
const out = process.argv.includes('--out') ? process.argv[process.argv.indexOf('--out') + 1]
  : path.join(__dirname, '..', '..', '..', 'src', 'Marrow.Core', 'Port', 'Voice', 'Orb', 'OrbSeedData.cs');

// the JSON text of each number, exactly as seeds.json spells it
const raw = bytes.toString('utf8');
function literals(preset, state) {
  const at = raw.indexOf('"' + preset + '"');
  const sAt = raw.indexOf('"' + state + '":[', at) + state.length + 4;
  const end = raw.indexOf(']', sAt);
  const items = raw.slice(sAt, end).split(',');
  const parsed = seeds[preset].stateSeeds[state];
  if (items.length !== 136 || parsed.length !== 136) throw new Error('136 floats expected');
  items.forEach((t, i) => { if (+t !== parsed[i]) throw new Error('text/parse mismatch at ' + i); });
  const lines = [];
  for (let i = 0; i < 136; i += 4) lines.push('        ' + items.slice(i, i + 4).map((t) => t + 'f').join(', ') + ',');
  return lines.join('\n');
}
const sha = crypto.createHash('sha256').update(bytes).digest('hex');
const block = (name, preset, state) => `    internal static readonly float[] ${name} =\n    [\n${literals(preset, state)}\n    ];\n`;
const cs = `// GENERATED by tests/fixtures/voice/make-orb-seed-source.js from tests/fixtures/voice/seeds.json (the owner's pasted exports, 2026-10-03;
// Liquid Orb Editor by LerSent001, MIT). Do not edit by hand: change seeds.json and run the script.
// PORT-ONLY, owner-ruled addition (OD-0091 fourth amendment: "the EXACT site exports"; first-release voice typing, VT-4, voice-SPEC V-11.1).
namespace Marrow.Core.Port.Voice.Orb;

/// <summary>The two presets' <c>stateSeeds</c> (136 floats each, the WGSL <c>Uniforms</c> layout), verbatim from seeds.json.</summary>
internal static class OrbSeedData
{
    /// <summary>SHA-256 of the seeds.json these literals were generated from.</summary>
    internal const string SourceSha256 = "${sha}";

    internal const string SiriBackground = "${seeds['siri-wave'].background}";
    internal const string MembraneBackground = "${seeds['voice-membrane'].background}";

${block('SiriIdle', 'siri-wave', 'idle')}
${block('SiriThinking', 'siri-wave', 'thinking')}
${block('MembraneIdle', 'voice-membrane', 'idle')}
${block('MembraneThinking', 'voice-membrane', 'thinking')}}
`;
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, cs);
console.log('wrote', out, cs.length, 'chars');
